// Admin-only pseudo-region for drafts where a stylist confirmed "south London"
// but not which side. Deliberately kept out of `regionOptions` itself (and out
// of data/locations.json, which feeds the public site's region filter) so it's
// never offered to visitors — but it still needs to pass validation wherever a
// draft's areaId is checked, and survive `regionOptions` being regenerated by
// the Locations settings editor (which only knows about data/locations.json).
// matchesRegion() in salon-index.mjs already treats areaId "south" as matching
// both south-east and south-west searches.
const southLondonRegionOption = { id: "south", label: "South London" };
