  app.post("/api/admin/stylists/booking-preview", requireAdmin, adminExpensiveRateLimit, async (req, res) => {
    const bookingUrl = cleanString(req.body?.bookingUrl);
    const websiteUrl = cleanString(req.body?.websiteUrl);
    const urls = {
      bookingUrl: bookingUrl && !isSocialOnlyUrl(bookingUrl) ? bookingUrl : "",
      websiteUrl: websiteUrl && !isSocialOnlyUrl(websiteUrl) ? websiteUrl : "",
    };

    if (!urls.bookingUrl && !urls.websiteUrl) {
      return res.status(400).json({ ok: false, message: "Add a machine-readable booking or website link first." });
    }

    const [bookingLinkCheck, websiteLinkCheck] = await Promise.all([
      urls.bookingUrl ? checkUrl("booking", urls.bookingUrl, { includeText: true }) : null,
      urls.websiteUrl && urls.websiteUrl !== urls.bookingUrl ? checkUrl("website", urls.websiteUrl, { includeText: true }) : null,
    ]);
    const bookingHtml = bookingLinkCheck?.status === "ok" ? bookingLinkCheck.responseText || "" : "";
    const websiteHtml = websiteLinkCheck?.status === "ok" ? websiteLinkCheck.responseText || "" : "";
    const embeddedBookingSources = await fetchEmbeddedBookingSources([
      { html: bookingHtml, url: urls.bookingUrl },
      { html: websiteHtml, url: urls.websiteUrl },
    ]);
    const enrichedBookingHtml = combineBookingHtml(bookingHtml, embeddedBookingSources);
    const serviceCheck = enrichedBookingHtml ? extractBookingServicesFromHtml(enrichedBookingHtml) : emptyServiceCheck();
    let priceCheck = await extractBestPriceCheck({
      booking: enrichedBookingHtml,
      website: websiteHtml,
      bookingUrl: embeddedBookingSources[0]?.url || urls.bookingUrl,
      websiteUrl: urls.websiteUrl,
      allowAiFallback: true,
    });

    if (priceCheck.confidence === "unknown") {
      priceCheck = await extractDirectSiteFallbackPriceCheck({
        bookingHtml: enrichedBookingHtml,
        websiteHtml,
        bookingUrl: urls.bookingUrl,
        websiteUrl: urls.websiteUrl,
        allowAiFallback: true,
      });
    }

    const acuityImageUrl = [urls.bookingUrl, ...embeddedBookingSources.map((source) => source.url)].find(
      (candidate) => isAcuityBookingUrl(candidate),
    );
    const imageTextCheck = acuityImageUrl ? await extractBookingImageTextQuotes(acuityImageUrl).catch(() => null) : null;

    res.json({
      ok: true,
      linkChecks: [
        bookingLinkCheck,
        websiteLinkCheck,
        ...embeddedBookingSources.map((source) => source.linkCheck),
      ].filter(Boolean).map(stripLinkCheckResponseText),
      serviceCheck,
      priceCheck,
      imageTextCheck,
    });
  });

  app.post("/api/admin/stylists/keyword-search", requireAdmin, async (req, res) => {
    const keywords = sanitizeKeywordSearchTerms(req.body?.keywords);
    if (!keywords.length) {
      return res.status(400).json({ ok: false, message: "Add at least one keyword." });
    }
    const selectedService = normalizeSelectedKeywordService(req.body?.selectedService);
    const searchKeywords = expandKeywordSearchTerms(keywords, { selectedService });

    const index = await readAdminSalonIndex();
    const offset = Math.max(Number(req.body?.offset || 0), 0);
    const limit = Math.min(Math.max(Number(req.body?.limit || 30), 1), 50);
    // Optional narrowing to salons already known to offer one of these
    // services — lets an admin scope a search (e.g. "who offers X" among
    // "salons that already do Y") instead of scanning the entire directory
    // page by page.
    const serviceFilter = (Array.isArray(req.body?.serviceFilter) ? req.body.serviceFilter : [])
      .map((service) => normalizeSelectedKeywordService(service))
      .filter(Boolean);
    const allSalons = index.salons || [];
    const salons = serviceFilter.length
      ? allSalons.filter((salon) => normalizeServices(salon.services || []).some((service) => serviceFilter.includes(service)))
      : allSalons;
    const batchSalons = salons.slice(offset, offset + limit);
    const checkedAt = today();
    const checks = await mapWithConcurrency(batchSalons, isHostedRuntime() ? 2 : 10, (salon) => withTimeout(
      searchSalonBookingKeywords(salon, searchKeywords, { selectedService }),
      isHostedRuntime() ? 14_000 : 9_000,
      buildKeywordSearchResult(salon, {
        status: "unsearchable",
        reason: "Timed out while searching booking or website page.",
        keywords: searchKeywords,
        selectedService,
      }),
    ), {
      delayMs: isHostedRuntime() ? 250 : 0,
    });
    const results = checks.filter((check) => check.matches.length > 0);
    const skippedCount = checks.filter((check) => check.status !== "searched").length;
    const checkedCount = Math.min(offset + batchSalons.length, salons.length);

    res.json({
      ok: true,
      keywords: searchKeywords,
      selectedService,
      requestedKeywords: keywords,
      results,
      checkedAt,
      offset,
      limit,
      batchCount: batchSalons.length,
      checkedCount,
      total: salons.length,
      skippedCount,
      nextOffset: offset + batchSalons.length < salons.length ? offset + batchSalons.length : null,
    });
  });

